"""
Aetherion Healthcare - Flask REST API Backend
Complete backend with all routes, auth, and database operations
"""

from flask import Flask, request, jsonify, send_file
from flask_cors import CORS
from functools import wraps
import mysql.connector
import jwt
import bcrypt
import uuid
from datetime import datetime, timedelta
import json
import os

# ============================================
# APP CONFIGURATION
# ============================================
app = Flask(__name__)
CORS(app, supports_credentials=True)

app.config['SECRET_KEY'] = 'aetherion-super-secret-key-2024'
app.config['JWT_EXPIRY_HOURS'] = 24
app.config['UPLOAD_FOLDER'] = 'uploads'

# ============================================
# DATABASE CONNECTION
# ============================================
def get_db():
    """Get database connection"""
    return mysql.connector.connect(
        host="localhost",
        user="root",
        password="",
        database="aetherion_healthcare"
    )

def query(sql, params=None, fetch=True):
    """Execute query and return results"""
    db = get_db()
    cursor = db.cursor(dictionary=True)
    try:
        cursor.execute(sql, params or ())
        if fetch:
            result = cursor.fetchall()
            return result
        db.commit()
        return cursor.lastrowid
    except Exception as e:
        db.rollback()
        raise e
    finally:
        cursor.close()
        db.close()

# ============================================
# AUTH DECORATORS
# ============================================
def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            return jsonify({'error': 'Token required'}), 401
        try:
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
            current_user = query("SELECT * FROM users WHERE id = %s", (data['user_id'],), fetch=True)
            if not current_user:
                return jsonify({'error': 'User not found'}), 401
            request.user = current_user[0]
        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token expired'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Invalid token'}), 401
        return f(*args, **kwargs)
    return decorated

def role_required(*roles):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            user_role = request.user.get('primary_role_id') or request.user.get('role', '')
            if user_role not in roles and 'admin' not in str(user_role):
                return jsonify({'error': 'Access denied'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

# ============================================
# HELPER FUNCTIONS
# ============================================
def generate_token(user_id, role):
    """Generate JWT token"""
    payload = {
        'user_id': user_id,
        'role': role,
        'exp': datetime.utcnow() + timedelta(hours=app.config['JWT_EXPIRY_HOURS']),
        'iat': datetime.utcnow()
    }
    return jwt.encode(payload, app.config['SECRET_KEY'], algorithm='HS256')

def hash_password(password):
    """Hash password"""
    return bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')

def check_password(password, hashed):
    """Check password"""
    return bcrypt.checkpw(password.encode('utf-8'), hashed.encode('utf-8'))

def generate_uuid():
    return str(uuid.uuid4())

